-- Update existing templates to use --cv-c1/--cv-c2 CSS variables for color theme support

UPDATE cv_templates SET stylesheet='body{margin:0;font-family:Inter,system-ui,sans-serif;color:#e5e7eb;background:#101225}.cv-root{max-width:900px;margin:auto;padding:28px;background:#11142f;border-radius:18px;box-shadow:0 20px 45px rgba(0,0,0,.35)}.cv-header{display:flex;justify-content:space-between;align-items:center;gap:24px;padding:24px;border-bottom:1px solid rgba(255,255,255,.08);background:linear-gradient(135deg,var(--cv-c1,#667eea),var(--cv-c2,#764ba2));border-radius:18px 18px 0 0}.cv-name{margin:0;font-size:2.5rem;color:#fff}.cv-subtitle{margin:4px 0 0;color:rgba(255,255,255,.8)}.cv-section{padding:24px}.cv-section:not(:first-of-type){border-top:1px solid rgba(255,255,255,.08)}.cv-title{margin:0 0 18px;font-size:1.2rem;letter-spacing:.08em;text-transform:uppercase;color:var(--cv-c1,#a5b4fc)}.cv-list{margin:0;padding:0;list-style:none}.cv-list li{margin-bottom:12px}.cv-label{color:rgba(255,255,255,.7)}.cv-skill{display:inline-flex;align-items:center;margin:0 8px 8px 0;padding:8px 12px;background:rgba(255,255,255,.08);border-radius:999px}.cv-cert-link{color:var(--cv-c1,#a5b4fc);text-decoration:none}.cv-cert-link:hover{text-decoration:underline}.cv-hobby{display:inline-block;margin:0 8px 8px 0;padding:6px 14px;background:rgba(255,255,255,.06);border-radius:999px;font-size:.9rem}',
html_template='<div class="cv-root"><section class="cv-header"><div><h1 class="cv-name">{{firstName}} {{lastName}}</h1><p class="cv-subtitle">{{jobTitle}}</p></div><div>{{#avatar}}<img src="{{avatar}}" alt="Avatar" style="width:100px;height:100px;border-radius:50%;object-fit:cover;border:3px solid rgba(255,255,255,.85)"/>{{/avatar}}</div></section><section class="cv-section"><h2 class="cv-title">Contact</h2><ul class="cv-list">{{#email}}<li><span class="cv-label">Email:</span> {{email}}</li>{{/email}}{{#phone}}<li><span class="cv-label">Phone:</span> {{phone}}</li>{{/phone}}{{#location}}<li><span class="cv-label">Location:</span> {{location}}</li>{{/location}}{{#linkedin}}<li><span class="cv-label">LinkedIn:</span> {{linkedin}}</li>{{/linkedin}}{{#github}}<li><span class="cv-label">GitHub:</span> {{github}}</li>{{/github}}</ul></section>{{#summary}}<section class="cv-section"><h2 class="cv-title">Summary</h2><p>{{summary}}</p></section>{{/summary}}{{#experience}}<section class="cv-section"><h2 class="cv-title">Experience</h2><ul class="cv-list">{{#experience}}<li><strong>{{title}}</strong> — {{company}}<br/><small class="cv-label">{{start}} — {{end}}</small><br/>{{description}}</li>{{/experience}}</ul></section>{{/experience}}{{#education}}<section class="cv-section"><h2 class="cv-title">Education</h2><ul class="cv-list">{{#education}}<li><strong>{{degree}}</strong>, {{school}} <span class="cv-label">({{year}})</span></li>{{/education}}</ul></section>{{/education}}{{#skills}}<section class="cv-section"><h2 class="cv-title">Skills</h2><div>{{#skills}}<span class="cv-skill">{{name}}</span>{{/skills}}</div></section>{{/skills}}{{#languages}}<section class="cv-section"><h2 class="cv-title">Languages</h2><ul class="cv-list">{{#languages}}<li>{{name}} — {{level}}</li>{{/languages}}</ul></section>{{/languages}}{{#certifications}}<section class="cv-section"><h2 class="cv-title">Certifications</h2><ul class="cv-list">{{#certifications}}<li><strong>{{name}}</strong> — {{issuer}} ({{year}}){{#link}} <a class="cv-cert-link" href="{{link}}" target="_blank">View</a>{{/link}}</li>{{/certifications}}</ul></section>{{/certifications}}{{#hasHobbies}}<section class="cv-section"><h2 class="cv-title">Hobbies</h2><div>{{#hobbiesList}}<span class="cv-hobby">{{name}}</span>{{/hobbiesList}}</div></section>{{/hasHobbies}}</div>'
WHERE name='Modern Slate';

UPDATE cv_templates SET stylesheet='body{margin:0;font-family:Georgia,serif;color:#1a1a1a;background:#f8f6f0}.cv-root{max-width:850px;margin:auto;padding:40px;background:#fff;box-shadow:0 4px 30px rgba(0,0,0,.08)}.cv-header{text-align:center;padding-bottom:24px;border-bottom:3px double var(--cv-c1,#bfa76a)}.cv-name{margin:0;font-size:2.4rem;color:#2c3e50;letter-spacing:.05em}.cv-subtitle{margin:8px 0 0;font-size:1.1rem;color:#7f8c8d;font-style:italic}.cv-section{padding:20px 0}.cv-section+.cv-section{border-top:1px solid #e8e8e8}.cv-title{margin:0 0 14px;font-size:1rem;letter-spacing:.12em;text-transform:uppercase;color:var(--cv-c1,#bfa76a);font-weight:700}.cv-list{margin:0;padding:0;list-style:none}.cv-list li{margin-bottom:10px;line-height:1.6}.cv-label{font-weight:600;color:#555}.cv-skill{display:inline-block;margin:0 8px 8px 0;padding:6px 14px;background:#f0ebe0;border:1px solid #d4c9a8;border-radius:4px;font-size:.9rem}.cv-cert-link{color:var(--cv-c1,#bfa76a);text-decoration:none}.cv-cert-link:hover{text-decoration:underline}.cv-hobby{display:inline-block;margin:0 8px 8px 0;padding:4px 12px;background:#f5f0e6;border-radius:4px;font-size:.9rem}',
html_template='<div class="cv-root"><section class="cv-header">{{#avatar}}<img src="{{avatar}}" alt="" style="width:100px;height:100px;border-radius:50%;object-fit:cover;border:3px solid var(--cv-c1,#bfa76a);margin-bottom:12px"/>{{/avatar}}<h1 class="cv-name">{{firstName}} {{lastName}}</h1><p class="cv-subtitle">{{jobTitle}}</p></section><section class="cv-section"><h2 class="cv-title">Contact</h2><ul class="cv-list">{{#email}}<li><span class="cv-label">Email:</span> {{email}}</li>{{/email}}{{#phone}}<li><span class="cv-label">Phone:</span> {{phone}}</li>{{/phone}}{{#location}}<li><span class="cv-label">Location:</span> {{location}}</li>{{/location}}{{#linkedin}}<li><span class="cv-label">LinkedIn:</span> {{linkedin}}</li>{{/linkedin}}{{#github}}<li><span class="cv-label">GitHub:</span> {{github}}</li>{{/github}}</ul></section>{{#summary}}<section class="cv-section"><h2 class="cv-title">Profile</h2><p>{{summary}}</p></section>{{/summary}}{{#experience}}<section class="cv-section"><h2 class="cv-title">Professional Experience</h2><ul class="cv-list">{{#experience}}<li><strong>{{title}}</strong> — {{company}}<br/><small class="cv-label">{{start}} – {{end}}</small><br/>{{description}}</li>{{/experience}}</ul></section>{{/experience}}{{#education}}<section class="cv-section"><h2 class="cv-title">Education</h2><ul class="cv-list">{{#education}}<li><strong>{{degree}}</strong>, {{school}} <span class="cv-label">({{year}})</span></li>{{/education}}</ul></section>{{/education}}{{#skills}}<section class="cv-section"><h2 class="cv-title">Skills</h2><div>{{#skills}}<span class="cv-skill">{{name}}</span>{{/skills}}</div></section>{{/skills}}{{#certifications}}<section class="cv-section"><h2 class="cv-title">Certifications</h2><ul class="cv-list">{{#certifications}}<li><strong>{{name}}</strong> — {{issuer}} ({{year}}){{#link}} <a class="cv-cert-link" href="{{link}}" target="_blank">View</a>{{/link}}</li>{{/certifications}}</ul></section>{{/certifications}}{{#hasHobbies}}<section class="cv-section"><h2 class="cv-title">Interests</h2><div>{{#hobbiesList}}<span class="cv-hobby">{{name}}</span>{{/hobbiesList}}</div></section>{{/hasHobbies}}</div>'
WHERE name='Executive Ivory';

UPDATE cv_templates SET stylesheet='body{margin:0;font-family:''Courier New'',monospace;color:#e0e0e0;background:#0d0d0d}.cv-root{max-width:880px;margin:auto;padding:32px;background:linear-gradient(145deg,#0d0d0d,#1a1a2e);border:1px solid var(--cv-c1,#00fff5);border-radius:12px;box-shadow:0 0 40px rgba(0,255,245,.08)}.cv-header{padding:24px;border-bottom:2px solid var(--cv-c1,#00fff5);display:flex;justify-content:space-between;align-items:center}.cv-name{margin:0;font-size:2.2rem;color:var(--cv-c1,#00fff5);text-shadow:0 0 20px rgba(0,255,245,.5)}.cv-subtitle{margin:6px 0 0;color:var(--cv-c2,#ff00aa);font-size:1rem}.cv-section{padding:20px 0}.cv-section+.cv-section{border-top:1px solid rgba(0,255,245,.15)}.cv-title{margin:0 0 14px;font-size:.95rem;letter-spacing:.15em;text-transform:uppercase;color:var(--cv-c2,#ff00aa);text-shadow:0 0 10px rgba(255,0,170,.4)}.cv-list{margin:0;padding:0;list-style:none}.cv-list li{margin-bottom:10px;padding-left:16px;border-left:2px solid var(--cv-c1,#00fff5)}.cv-label{color:#888}.cv-skill{display:inline-block;margin:0 8px 8px 0;padding:6px 14px;background:rgba(0,255,245,.08);border:1px solid rgba(0,255,245,.3);border-radius:20px;font-size:.85rem;color:var(--cv-c1,#00fff5)}.cv-cert-link{color:var(--cv-c1,#00fff5);text-decoration:none}.cv-hobby{display:inline-block;margin:0 8px 8px 0;padding:4px 12px;background:rgba(0,255,245,.06);border-radius:20px;font-size:.85rem;color:var(--cv-c1,#00fff5)}',
html_template='<div class="cv-root"><section class="cv-header"><div><h1 class="cv-name">{{firstName}} {{lastName}}</h1><p class="cv-subtitle">{{jobTitle}}</p></div><div>{{#avatar}}<img src="{{avatar}}" alt="" style="width:90px;height:90px;border-radius:50%;object-fit:cover;border:2px solid var(--cv-c1,#00fff5);box-shadow:0 0 20px rgba(0,255,245,.3)"/>{{/avatar}}</div></section><section class="cv-section"><h2 class="cv-title">// Contact</h2><ul class="cv-list">{{#email}}<li><span class="cv-label">Email:</span> {{email}}</li>{{/email}}{{#phone}}<li><span class="cv-label">Phone:</span> {{phone}}</li>{{/phone}}{{#location}}<li><span class="cv-label">Location:</span> {{location}}</li>{{/location}}</ul></section>{{#summary}}<section class="cv-section"><h2 class="cv-title">// About</h2><p>{{summary}}</p></section>{{/summary}}{{#experience}}<section class="cv-section"><h2 class="cv-title">// Experience</h2><ul class="cv-list">{{#experience}}<li><strong>{{title}}</strong> @ {{company}}<br/><small class="cv-label">{{start}} → {{end}}</small><br/>{{description}}</li>{{/experience}}</ul></section>{{/experience}}{{#education}}<section class="cv-section"><h2 class="cv-title">// Education</h2><ul class="cv-list">{{#education}}<li><strong>{{degree}}</strong> — {{school}} <span class="cv-label">({{year}})</span></li>{{/education}}</ul></section>{{/education}}{{#skills}}<section class="cv-section"><h2 class="cv-title">// Tech Stack</h2><div>{{#skills}}<span class="cv-skill">{{name}}</span>{{/skills}}</div></section>{{/skills}}{{#certifications}}<section class="cv-section"><h2 class="cv-title">// Certs</h2><ul class="cv-list">{{#certifications}}<li>{{name}} — {{issuer}} ({{year}}){{#link}} <a class="cv-cert-link" href="{{link}}" target="_blank">[link]</a>{{/link}}</li>{{/certifications}}</ul></section>{{/certifications}}{{#hasHobbies}}<section class="cv-section"><h2 class="cv-title">// Hobbies</h2><div>{{#hobbiesList}}<span class="cv-hobby">{{name}}</span>{{/hobbiesList}}</div></section>{{/hasHobbies}}</div>'
WHERE name='Neon Pulse';

UPDATE cv_templates SET stylesheet='body{margin:0;font-family:Inter,Helvetica,Arial,sans-serif;color:#333;background:#fafafa}.cv-root{max-width:800px;margin:auto;padding:48px;background:#fff}.cv-header{margin-bottom:32px;border-bottom:2px solid var(--cv-c1,#667eea);padding-bottom:16px}.cv-name{margin:0;font-size:2rem;font-weight:300;color:#111;letter-spacing:.02em}.cv-subtitle{margin:4px 0 0;font-size:1rem;color:var(--cv-c1,#888);font-weight:400}.cv-section{padding:16px 0}.cv-section+.cv-section{border-top:1px solid #eee}.cv-title{margin:0 0 12px;font-size:.75rem;letter-spacing:.2em;text-transform:uppercase;color:var(--cv-c1,#aaa);font-weight:600}.cv-list{margin:0;padding:0;list-style:none}.cv-list li{margin-bottom:8px;font-size:.95rem;line-height:1.7}.cv-label{color:#999}.cv-skill{display:inline-block;margin:0 6px 6px 0;padding:4px 12px;background:#f5f5f5;border-radius:3px;font-size:.85rem;color:#555}.cv-cert-link{color:var(--cv-c1,#667eea);text-decoration:none}.cv-hobby{display:inline-block;margin:0 6px 6px 0;padding:4px 12px;background:#f5f5f5;border-radius:3px;font-size:.85rem}',
html_template='<div class="cv-root"><header class="cv-header">{{#avatar}}<img src="{{avatar}}" alt="" style="width:80px;height:80px;border-radius:50%;object-fit:cover;float:right;border:2px solid var(--cv-c1,#667eea)"/>{{/avatar}}<h1 class="cv-name">{{firstName}} {{lastName}}</h1><p class="cv-subtitle">{{jobTitle}}</p></header><section class="cv-section"><h2 class="cv-title">Contact</h2><ul class="cv-list">{{#email}}<li>{{email}}</li>{{/email}}{{#phone}}<li>{{phone}}</li>{{/phone}}{{#location}}<li>{{location}}</li>{{/location}}{{#linkedin}}<li>{{linkedin}}</li>{{/linkedin}}</ul></section>{{#summary}}<section class="cv-section"><h2 class="cv-title">Summary</h2><p>{{summary}}</p></section>{{/summary}}{{#experience}}<section class="cv-section"><h2 class="cv-title">Experience</h2><ul class="cv-list">{{#experience}}<li><strong>{{title}}</strong> — {{company}}<br/><span class="cv-label">{{start}} – {{end}}</span><br/>{{description}}</li>{{/experience}}</ul></section>{{/experience}}{{#education}}<section class="cv-section"><h2 class="cv-title">Education</h2><ul class="cv-list">{{#education}}<li><strong>{{degree}}</strong>, {{school}} ({{year}})</li>{{/education}}</ul></section>{{/education}}{{#skills}}<section class="cv-section"><h2 class="cv-title">Skills</h2><div>{{#skills}}<span class="cv-skill">{{name}}</span>{{/skills}}</div></section>{{/skills}}{{#certifications}}<section class="cv-section"><h2 class="cv-title">Certifications</h2><ul class="cv-list">{{#certifications}}<li>{{name}} — {{issuer}} ({{year}}){{#link}} <a class="cv-cert-link" href="{{link}}" target="_blank">View</a>{{/link}}</li>{{/certifications}}</ul></section>{{/certifications}}{{#hasHobbies}}<section class="cv-section"><h2 class="cv-title">Hobbies</h2><div>{{#hobbiesList}}<span class="cv-hobby">{{name}}</span>{{/hobbiesList}}</div></section>{{/hasHobbies}}</div>'
WHERE name='Minimal Breeze';

UPDATE cv_templates SET stylesheet='body{margin:0;font-family:Inter,system-ui,sans-serif;color:#1e293b;background:#f1f5f9}.cv-root{max-width:900px;margin:auto;display:grid;grid-template-columns:280px 1fr;min-height:100vh}.cv-sidebar{background:linear-gradient(180deg,var(--cv-c1,#1e3a5f),var(--cv-c2,#0f2744));color:#e2e8f0;padding:32px 24px}.cv-sidebar .cv-name{font-size:1.6rem;color:#fff;margin:16px 0 4px}.cv-sidebar .cv-subtitle{color:#94a3b8;font-size:.9rem;margin:0 0 24px}.cv-sidebar .cv-title{font-size:.75rem;letter-spacing:.15em;text-transform:uppercase;color:var(--cv-c1,#60a5fa);margin:20px 0 10px;font-weight:700}.cv-sidebar .cv-list{margin:0;padding:0;list-style:none}.cv-sidebar .cv-list li{margin-bottom:8px;font-size:.9rem;color:#cbd5e1}.cv-sidebar .cv-skill{display:inline-block;margin:0 6px 6px 0;padding:4px 10px;background:rgba(96,165,250,.15);border:1px solid rgba(96,165,250,.3);border-radius:12px;font-size:.8rem;color:#93c5fd}.cv-main{padding:32px}.cv-main .cv-title{font-size:.8rem;letter-spacing:.12em;text-transform:uppercase;color:var(--cv-c1,#1e3a5f);border-bottom:2px solid var(--cv-c1,#60a5fa);padding-bottom:6px;margin:24px 0 14px;font-weight:700}.cv-main .cv-list{margin:0;padding:0;list-style:none}.cv-main .cv-list li{margin-bottom:14px;line-height:1.6}.cv-main .cv-label{color:#64748b;font-size:.85rem}.cv-cert-link{color:var(--cv-c1,#1e3a5f);text-decoration:none}.cv-hobby{display:inline-block;margin:0 6px 6px 0;padding:4px 10px;background:rgba(96,165,250,.1);border-radius:12px;font-size:.8rem}',
html_template='<div class="cv-root"><aside class="cv-sidebar">{{#avatar}}<img src="{{avatar}}" alt="" style="width:120px;height:120px;border-radius:50%;object-fit:cover;border:3px solid var(--cv-c1,#60a5fa);display:block;margin:0 auto"/>{{/avatar}}<h1 class="cv-name">{{firstName}} {{lastName}}</h1><p class="cv-subtitle">{{jobTitle}}</p><h2 class="cv-title">Contact</h2><ul class="cv-list">{{#email}}<li>{{email}}</li>{{/email}}{{#phone}}<li>{{phone}}</li>{{/phone}}{{#location}}<li>{{location}}</li>{{/location}}{{#linkedin}}<li>{{linkedin}}</li>{{/linkedin}}</ul>{{#skills}}<h2 class="cv-title">Skills</h2><div>{{#skills}}<span class="cv-skill">{{name}}</span>{{/skills}}</div>{{/skills}}{{#languages}}<h2 class="cv-title">Languages</h2><ul class="cv-list">{{#languages}}<li>{{name}} — {{level}}</li>{{/languages}}</ul>{{/languages}}</aside><main class="cv-main">{{#summary}}<h2 class="cv-title">Profile</h2><p>{{summary}}</p>{{/summary}}{{#experience}}<h2 class="cv-title">Experience</h2><ul class="cv-list">{{#experience}}<li><strong>{{title}}</strong> — {{company}}<br/><span class="cv-label">{{start}} – {{end}}</span><br/>{{description}}</li>{{/experience}}</ul>{{/experience}}{{#education}}<h2 class="cv-title">Education</h2><ul class="cv-list">{{#education}}<li><strong>{{degree}}</strong>, {{school}} <span class="cv-label">({{year}})</span></li>{{/education}}</ul>{{/education}}{{#certifications}}<h2 class="cv-title">Certifications</h2><ul class="cv-list">{{#certifications}}<li><strong>{{name}}</strong> — {{issuer}} ({{year}}){{#link}} <a class="cv-cert-link" href="{{link}}" target="_blank">View</a>{{/link}}</li>{{/certifications}}</ul>{{/certifications}}{{#hasHobbies}}<h2 class="cv-title">Interests</h2><div>{{#hobbiesList}}<span class="cv-hobby">{{name}}</span>{{/hobbiesList}}</div>{{/hasHobbies}}</main></div>'
WHERE name='Royal Azure';

-- Issue 27: Template 6 - Classic Word (plain, like a Word document)
INSERT OR IGNORE INTO cv_templates (name,description,preview_img,stylesheet,html_template,is_active) VALUES('Classic Word','Plain professional layout resembling a traditional Word document.','/templates/classic-word.png','body{margin:0;font-family:''Times New Roman'',Times,serif;color:#000;background:#fff;font-size:12pt;line-height:1.5}.cv-root{max-width:800px;margin:auto;padding:40px 60px}.cv-header{text-align:center;border-bottom:2px solid #000;padding-bottom:12px;margin-bottom:20px}.cv-name{margin:0;font-size:22pt;font-weight:bold;text-transform:uppercase;letter-spacing:2px}.cv-subtitle{margin:4px 0 0;font-size:12pt;color:#333}.cv-contact{text-align:center;margin-bottom:20px;font-size:10pt;color:#444}.cv-contact span{margin:0 8px}.cv-section{margin-bottom:16px}.cv-title{margin:0 0 8px;font-size:12pt;font-weight:bold;text-transform:uppercase;border-bottom:1px solid #000;padding-bottom:4px}.cv-list{margin:0;padding:0;list-style:none}.cv-list li{margin-bottom:8px}.cv-label{font-weight:bold}.cv-skill{display:inline;margin-right:8px}.cv-skill::after{content:'' • ''}.cv-skill:last-child::after{content:''''}.cv-cert-link{color:#000;text-decoration:underline}.cv-hobby{display:inline}.cv-hobby::after{content:'', ''}.cv-hobby:last-child::after{content:''''}','<div class="cv-root"><header class="cv-header"><h1 class="cv-name">{{firstName}} {{lastName}}</h1><p class="cv-subtitle">{{jobTitle}}</p></header><div class="cv-contact">{{#email}}<span>{{email}}</span>{{/email}}{{#phone}}<span>{{phone}}</span>{{/phone}}{{#location}}<span>{{location}}</span>{{/location}}{{#linkedin}}<span>{{linkedin}}</span>{{/linkedin}}</div>{{#summary}}<section class="cv-section"><h2 class="cv-title">Professional Summary</h2><p>{{summary}}</p></section>{{/summary}}{{#experience}}<section class="cv-section"><h2 class="cv-title">Work Experience</h2><ul class="cv-list">{{#experience}}<li><strong>{{title}}</strong>, {{company}}<br/><em>{{start}} – {{end}}</em><br/>{{description}}</li>{{/experience}}</ul></section>{{/experience}}{{#education}}<section class="cv-section"><h2 class="cv-title">Education</h2><ul class="cv-list">{{#education}}<li><strong>{{degree}}</strong>, {{school}} ({{year}})</li>{{/education}}</ul></section>{{/education}}{{#skills}}<section class="cv-section"><h2 class="cv-title">Skills</h2><div>{{#skills}}<span class="cv-skill">{{name}}</span>{{/skills}}</div></section>{{/skills}}{{#languages}}<section class="cv-section"><h2 class="cv-title">Languages</h2><ul class="cv-list">{{#languages}}<li>{{name}} — {{level}}</li>{{/languages}}</ul></section>{{/languages}}{{#certifications}}<section class="cv-section"><h2 class="cv-title">Certifications</h2><ul class="cv-list">{{#certifications}}<li>{{name}}, {{issuer}} ({{year}}){{#link}} — <a class="cv-cert-link" href="{{link}}" target="_blank">View Certificate</a>{{/link}}</li>{{/certifications}}</ul></section>{{/certifications}}{{#hasHobbies}}<section class="cv-section"><h2 class="cv-title">Hobbies &amp; Interests</h2><div>{{#hobbiesList}}<span class="cv-hobby">{{name}}</span>{{/hobbiesList}}</div></section>{{/hasHobbies}}</div>',1);
